 @Test public void primaryTouchAndFixedStickFollow()throws Exception{
  try(ActivityScenario<GameActivity> scene=ActivityScenario.launch(prepare(54,17354,400,true,false))){
   frozen(scene);MyGLSurfaceView[] gl={null};ItemOverlay[] h={null};Rect b=new Rect(),hb=new Rect();scene.onActivity(a->{gl[0]=a.findViewById(R.id.mySurfaceView);h[0]=a.findViewById(R.id.item_overlay);gl[0].getGlobalVisibleRect(b);h[0].getGlobalVisibleRect(hb);});readyGL(gl[0],4);
   long hash=NativeInterface.stateHash();float old=gl[0].camera.left,px=b.left+gl[0].getWidth()*(old>400?.30f:.70f),py=b.top+gl[0].getHeight()*.45f;int ex=gl[0].camera.mapX(px-b.left,b.width()),ey=gl[0].camera.mapY(py-b.top,b.height());long down=SystemClock.uptimeMillis();touch(down,0,px,py);SystemClock.sleep(520);touch(down,2,px,py);SystemClock.sleep(160);touch(down,1,px,py);short[][] first=targets(scene);Assert.assertEquals(ex,first[0][0]);Assert.assertEquals(ey,first[1][0]);Assert.assertTrue(Math.abs(gl[0].camera.left-old)>40);Assert.assertEquals(hash,NativeInterface.stateHash());float goal=gl[0].camera.left;SystemClock.sleep(220);Assert.assertArrayEquals(first[0],targets(scene)[0]);picture("world173-touch-follow.jpg");
   miniTap(h[0],hb,1300,760,false);SystemClock.sleep(150);Assert.assertFalse(gl[0].camera.following);float pan=gl[0].camera.left;SystemClock.sleep(180);Assert.assertEquals(pan,gl[0].camera.left,.1f);Assert.assertArrayEquals(first[0],targets(scene)[0]);picture("world173-minimap-inspection.jpg");
   float dp=context().getResources().getDisplayMetrics().density;long stick=SystemClock.uptimeMillis();touch(stick,0,hb.left+76*dp,hb.bottom-66*dp);touch(stick,2,hb.left+115*dp,hb.bottom-66*dp);SystemClock.sleep(450);short[][] moving=targets(scene);Assert.assertTrue(gl[0].camera.following&&!gl[0].camera.overview);touch(stick,1,hb.left+115*dp,hb.bottom-66*dp);moving=targets(scene);SystemClock.sleep(120);Assert.assertArrayEquals(moving[0],targets(scene)[0]);Assert.assertEquals(hash,NativeInterface.stateHash());picture("world173-stick-follow.jpg");
   long f=gl[0].framesDrawn();scene.onActivity(a->{gl[0].onPause();gl[0].onResume();});long until=SystemClock.uptimeMillis()+7000;while(gl[0].framesDrawn()<=f&&SystemClock.uptimeMillis()<until)SystemClock.sleep(30);readyGL(gl[0],4);Assert.assertArrayEquals(moving[0],targets(scene)[0]);Assert.assertEquals(hash,NativeInterface.stateHash());
   scene.onActivity(a->{try{invoke(h[0],"showGuide");}catch(Exception e){throw new RuntimeException(e);}});SystemClock.sleep(180);android.view.accessibility.AccessibilityNodeInfo root=androidx.test.platform.app.InstrumentationRegistry.getInstrumentation().getUiAutomation().getRootInActiveWindow();Assert.assertTrue(!root.findAccessibilityNodeInfosByText("20种战场道具").isEmpty()||!root.findAccessibilityNodeInfosByText("20 battlefield items").isEmpty());picture("world173-guide20.jpg");Assert.assertTrue(androidx.test.platform.app.InstrumentationRegistry.getInstrumentation().getUiAutomation().performGlobalAction(android.accessibilityservice.AccessibilityService.GLOBAL_ACTION_BACK));SystemClock.sleep(100);
   write("world173-camera.json",new JSONObject().put("status","PASS").put("target_x",ex).put("target_y",ey).put("camera_left_before",old).put("camera_left_after",goal).put("stationary_finger_no_feedback",true).put("release_keeps_target",true).put("manual_minimap_no_command",true).put("stick_resumes_follow",true).put("egl_resume",true).put("rule_hash_unchanged",true).put("real_touch",true).put("controlled_pause",true).put("models",0));
  }
 }
 static int findKind(int[] s,int kind){for(int k=0;k<SnapshotItems.slots(s);k++)if(s[SnapshotItems.offset(s,k)]==kind)return k;return -1;}
 static void naturalWave(){for(int n=0;n<2200&&NativeInterface.itemSnapshot()[2]==0;n++)NativeInterface.stepDots();}
 static void moveTo(int team,int x,int y){short[] xx=IDLE.clone(),yy=IDLE.clone();xx[0]=(short)x;yy[0]=(short)y;NativeInterface.setPlayerPosition(team,xx,yy);}
 @Test public void cloakOwnEnemyObserverAndExpiry()throws Exception{
  Intent intent=prepare(1,179,100,true,false);StaticBits.team=1;
  try(ActivityScenario<GameActivity> scene=ActivityScenario.launch(intent)){
   frozen(scene);idle();MyGLSurfaceView[] gl={null};scene.onActivity(a->gl[0]=a.findViewById(R.id.mySurfaceView));readyGL(gl[0],0);naturalWave();int[] wave=NativeInterface.itemSnapshot();int slot=findKind(wave,18);Assert.assertTrue(slot>=0);int at=SnapshotItems.offset(wave,slot);moveTo(0,wave[at+1],wave[at+2]);for(int n=0;n<2500&&NativeInterface.itemSnapshot()[25+18]==0;n++)NativeInterface.stepDots();int[] hidden=NativeInterface.itemSnapshot();Assert.assertTrue("natural cloak acquired",hidden[25+18]>0);
   byte[] floor=NativeInterface.modelTerrain();int awayX=-1,awayY=-1;outer:for(int yy=Math.max(20,wave[at+2]-80);yy<Math.min(460,wave[at+2]+80);yy+=4)for(int xx=Math.max(25,wave[at+1]-80);xx<Math.min(775,wave[at+1]+80);xx+=4){int dx=xx-wave[at+1],dy=yy-wave[at+2],dist=dx*dx+dy*dy;if(dist<35*35||dist>75*75)continue;boolean clear=true;int length=Math.max(Math.abs(dx),Math.abs(dy));for(int n=0;n<=length;n++)if(floor[(wave[at+2]+dy*n/Math.max(1,length))*800+wave[at+1]+dx*n/Math.max(1,length)]!=0)clear=false;for(int y=-8;y<=8&&clear;y++)for(int x=-8;x<=8;x++)if(floor[(yy+y)*800+xx+x]!=0)clear=false;for(int k=0;k<6;k++){int o=SnapshotItems.offset(hidden,k);if(hidden[o]>=0&&Math.hypot(xx-hidden[o+1],yy-hidden[o+2])<50)clear=false;}if(clear){awayX=xx;awayY=yy;break outer;}}
   Assert.assertTrue("clear presentation patch away from pickup icons",awayX>=0);moveTo(0,awayX,awayY);for(int n=0;n<160;n++){NativeInterface.stepDots();int[] mass=NativeInterface.aiSnapshot();if(Math.hypot(mass[4]-awayX,mass[5]-awayY)<8)break;}Assert.assertTrue(NativeInterface.itemSnapshot()[43]>0);idle();int[] army=NativeInterface.aiSnapshot();Rect screen=new Rect();scene.onActivity(a->gl[0].getGlobalVisibleRect(screen));int cropX=Math.round(screen.left+gl[0].camera.screenX(army[4],gl[0].getWidth())),cropY=Math.round(screen.top+gl[0].camera.screenY(army[5],gl[0].getHeight()));
   long hash=NativeInterface.stateHash();SystemClock.sleep(180);picture("world173-cloak-enemy-hidden.jpg");int[] mini=NativeInterface.minimapSnapshot(false);for(int k=0;k<mini[4];k++)Assert.assertNotEquals(0,mini[5+k*4]);scene.onActivity(a->a.getIntent().putExtra("spectator",true));SystemClock.sleep(180);picture("world173-cloak-observer.jpg");Assert.assertEquals(hash,NativeInterface.stateHash());scene.onActivity(a->a.getIntent().putExtra("spectator",false));SystemClock.sleep(140);
   NativeInterface.configureAlliances(new int[]{0,0,1,1,2,2});SystemClock.sleep(160);picture("world173-cloak-ally-ghost.jpg");mini=NativeInterface.minimapSnapshot(false);boolean ally=false;for(int k=0;k<mini[4];k++)ally|=mini[5+k*4]==0;Assert.assertTrue(ally);int[] after=NativeInterface.itemSnapshot();int begin=after[0],remaining=after[43];for(int n=0;n<900&&NativeInterface.itemSnapshot()[43]>0;n++)NativeInterface.stepDots();Assert.assertEquals(0,NativeInterface.itemSnapshot()[43]);SystemClock.sleep(160);picture("world173-cloak-expired.jpg");
   write("world173-cloak.json",new JSONObject().put("status","PASS").put("natural_seed",179).put("actor",0).put("enemy_viewer",1).put("crop_screen_x",cropX).put("crop_screen_y",cropY).put("enemy_minimap_hidden",true).put("observer_rule_hash_stable",true).put("allied_minimap_visible",true).put("remaining_at_capture_ms",remaining).put("expired_after_ms",NativeInterface.itemSnapshot()[0]-begin).put("models",0).put("controlled_steps",true));
  }
 }
 @Test public void rewindOnceAndPairedWaveInApp()throws Exception{
  Intent intent=prepare(1,105,100,true,false);StaticBits.team=2;
  try(ActivityScenario<GameActivity> scene=ActivityScenario.launch(intent)){
   frozen(scene);idle();naturalWave();int[] first=NativeInterface.itemSnapshot();int slot=findKind(first,4);Assert.assertTrue(slot>=0&&findKind(first,13)>=0);Assert.assertTrue(SnapshotItems.rewindSpawned(first));int at=SnapshotItems.offset(first,slot);moveTo(2,first[at+1],first[at+2]);for(int n=0;n<2800&&NativeInterface.itemSnapshot()[146]==0;n++)NativeInterface.stepDots();Assert.assertEquals(1,NativeInterface.itemSnapshot()[146]);Assert.assertTrue(SnapshotItems.rewindSpawned(NativeInterface.itemSnapshot()));SystemClock.sleep(150);picture("world173-rewind-regroup.jpg");scene.onActivity(a->{try{invoke(a,"syncRewind");}catch(Exception e){throw new RuntimeException(e);}});idle();naturalWave();int[] after=NativeInterface.itemSnapshot();Assert.assertEquals(-1,findKind(after,4));Assert.assertTrue(SnapshotItems.rewindSpawned(after));int[] powers={0,1,2,3,4,5,6,7,8,18},counters={9,10,11,12,13,14,15,16,17,19};for(int k=0;k<10;k++)if(findKind(after,powers[k])>=0)Assert.assertTrue(findKind(after,counters[k])>=0);SystemClock.sleep(170);picture("world173-paired-wave-after-rewind.jpg");
   write("world173-rewind.json",new JSONObject().put("status","PASS").put("natural_seed",105).put("first_reset_with_causal_counter",true).put("appearance_lock_retained",true).put("next_wave_without_reset",true).put("paired_powers",true).put("next_count",SnapshotItems.count(after)).put("models",0));
  }
 }
 @Test public void healthAndDirectMinimapTeleport()throws Exception{
  Intent intent=prepare(1,101,100,true,false);StaticBits.team=1;
  try(ActivityScenario<GameActivity> scene=ActivityScenario.launch(intent)){
   frozen(scene);MyGLSurfaceView[] gl={null};ItemOverlay[] h={null};Rect bounds=new Rect();scene.onActivity(a->{gl[0]=a.findViewById(R.id.mySurfaceView);h[0]=a.findViewById(R.id.item_overlay);h[0].getGlobalVisibleRect(bounds);});readyGL(gl[0],0);idle();
   for(int n=0;n<2000&&NativeInterface.itemSnapshot()[2]==0;n++)NativeInterface.stepDots();int[] wave=NativeInterface.itemSnapshot();int slot=-1;for(int k=0;k<SnapshotItems.slots(wave);k++)if(wave[SnapshotItems.offset(wave,k)]==3)slot=k;Assert.assertTrue("natural teleport fixture",slot>=0);int at=SnapshotItems.offset(wave,slot),x=wave[at+1],y=wave[at+2];short[] tx=IDLE.clone(),ty=IDLE.clone();tx[0]=(short)x;ty[0]=(short)y;NativeInterface.setPlayerPosition(1,tx,ty);
   int[] contact=null;for(int n=0;n<1400;n++){NativeInterface.stepDots();int[] now=NativeInterface.itemSnapshot();if(SnapshotItems.hp(now,slot)<1200){contact=now;break;}}
   Assert.assertNotNull("contact reached",contact);Assert.assertEquals(3,contact[SnapshotItems.offset(contact,slot)]);Assert.assertEquals(0,contact[157]);Assert.assertTrue(SnapshotItems.hp(contact,slot)>=1196);SystemClock.sleep(150);picture("world173-item-first-contact.jpg");
   for(int n=0;n<150;n++)NativeInterface.stepDots();int[] middle=NativeInterface.itemSnapshot();Assert.assertEquals(3,middle[SnapshotItems.offset(middle,slot)]);Assert.assertTrue(SnapshotItems.hp(middle,slot)>0&&SnapshotItems.hp(middle,slot)<1200);SystemClock.sleep(160);picture("world173-item-half-hp.jpg");int[] held=NativeInterface.itemSnapshot();SystemClock.sleep(180);Assert.assertArrayEquals("paused HP does not tick",held,NativeInterface.itemSnapshot());
   for(int n=0;n<1500&&NativeInterface.itemSnapshot()[157]!=3;n++)NativeInterface.stepDots();Assert.assertEquals(3,NativeInterface.itemSnapshot()[157]);NativeInterface.setPlayerPosition(1,IDLE,IDLE);SystemClock.sleep(180);picture("world173-minimap-teleport-ready.jpg");Assert.assertFalse((Boolean)get(h[0],"aiming"));
   byte[] wall=NativeInterface.modelTerrain();int wx=-1,wy=-1,fx=-1,fy=-1;for(int yy=20;yy<460;yy+=8)for(int xx=25;xx<775;xx+=8){boolean rock=true,floor=true;for(int dy=-3;dy<=3;dy++)for(int dx=-3;dx<=3;dx++){rock&=wall[(yy+dy)*800+xx+dx]!=0;floor&=wall[(yy+dy)*800+xx+dx]==0;}if(rock&&wx<0){wx=xx;wy=yy;}if(floor&&xx>450&&fx<0){fx=xx;fy=yy;}}Assert.assertTrue(wx>=0&&fx>=0);
   miniTap(h[0],bounds,wx,wy,true);apply(scene);NativeInterface.stepDots();Assert.assertEquals("wall keeps teleport",3,NativeInterface.itemSnapshot()[157]);SystemClock.sleep(180);picture("world173-minimap-wall-rejected.jpg");
   int armyBefore=NativeInterface.itemSnapshot()[14];miniTap(h[0],bounds,fx,fy,true);short[][] selected=targets(scene);Assert.assertEquals(-3,selected[0][4]);Assert.assertEquals(fx,selected[0][3]);Assert.assertEquals(fy,selected[1][3]);apply(scene);NativeInterface.stepDots();int[] done=NativeInterface.itemSnapshot();Assert.assertEquals(0,done[157]);Assert.assertEquals(armyBefore,done[11]);NativeInterface.setPlayerPosition(1,IDLE,IDLE);SystemClock.sleep(180);picture("world173-minimap-teleported.jpg");Assert.assertTrue(((Integer)get(h[0],"lastCameraTeleport"))>0);
   long before=gl[0].framesDrawn();scene.onActivity(a->{gl[0].onPause();gl[0].onResume();});long deadline=SystemClock.uptimeMillis()+5000;while(gl[0].framesDrawn()<=before&&SystemClock.uptimeMillis()<deadline)SystemClock.sleep(30);Assert.assertTrue(gl[0].framesDrawn()>before);Assert.assertArrayEquals(done,NativeInterface.itemSnapshot());
   write("world173-health-teleport.json",new JSONObject().put("status","PASS").put("natural_pickup",true).put("first_contact_hp",SnapshotItems.hp(contact,slot)).put("middle_hp",SnapshotItems.hp(middle,slot)).put("paused_hp_stable",true).put("no_bottom_card_required",true).put("wall_rejected_retained",true).put("selected_xy",new JSONArray().put(fx).put(fy)).put("teleported",armyBefore).put("egl_stable",true).put("models",0).put("controlled_native_steps",true));
  }
 }




 static void fingers(long down,int action,int count,int[] ids,float[] xx,float[] yy){MotionEvent.PointerProperties[] props=new MotionEvent.PointerProperties[count];MotionEvent.PointerCoords[] coords=new MotionEvent.PointerCoords[count];for(int k=0;k<count;k++){props[k]=new MotionEvent.PointerProperties();props[k].id=ids[k];props[k].toolType=MotionEvent.TOOL_TYPE_FINGER;coords[k]=new MotionEvent.PointerCoords();coords[k].x=xx[k];coords[k].y=yy[k];coords[k].pressure=1;coords[k].size=1;}MotionEvent e=MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,count,props,coords,0,0,1,1,0,0,InputDevice.SOURCE_TOUCHSCREEN,0);Assert.assertTrue(androidx.test.platform.app.InstrumentationRegistry.getInstrumentation().getUiAutomation().injectInputEvent(e,true));e.recycle();}
 @Test public void fiveTouchesKeepTheirWorldTargets()throws Exception{
  try(ActivityScenario<GameActivity> scene=ActivityScenario.launch(prepare(54,17354,400,true,false))){
   frozen(scene);MyGLSurfaceView[] gl={null};Rect b=new Rect();scene.onActivity(a->{gl[0]=a.findViewById(R.id.mySurfaceView);gl[0].getGlobalVisibleRect(b);});readyGL(gl[0],4);long hash=NativeInterface.stateHash();int[] ids={0,3,7,11,19};float[] xx={b.left+b.width()*(gl[0].camera.left>400?.3f:.7f),b.left+b.width()*.35f,b.left+b.width()*.5f,b.left+b.width()*.45f,b.left+b.width()*.6f},yy={b.top+b.height()*.45f,b.top+b.height()*.55f,b.top+b.height()*.6f,b.top+b.height()*.35f,b.top+b.height()*.4f};short[] ex=new short[5],ey=new short[5];long down=SystemClock.uptimeMillis();
   for(int k=0;k<5;k++){ex[k]=gl[0].camera.mapX(xx[k]-b.left,b.width());ey[k]=gl[0].camera.mapY(yy[k]-b.top,b.height());fingers(down,k==0?0:5|(k<<8),k+1,ids,xx,yy);SystemClock.sleep(k==0?900:70);short[][] targets=targets(scene);for(int t=0;t<=k;t++){Assert.assertEquals(ex[t],targets[0][t],1);Assert.assertEquals(ey[t],targets[1][t],1);}}
   fingers(down,2,5,ids,xx,yy);SystemClock.sleep(120);short[][] all=targets(scene);for(int t=0;t<5;t++){Assert.assertEquals(ex[t],all[0][t],1);Assert.assertEquals(ey[t],all[1][t],1);}picture("world173-five-finger.jpg");
   for(int count=5;count>=2;count--)fingers(down,6|((count-1)<<8),count,ids,xx,yy);fingers(down,1,1,ids,xx,yy);SystemClock.sleep(130);short[][] released=targets(scene);Assert.assertEquals(all[0][0],released[0][0]);Assert.assertEquals(all[1][0],released[1][0]);Assert.assertEquals(hash,NativeInterface.stateHash());write("world173-five-finger.json",new JSONObject().put("status","PASS").put("actual_pointer_ids",new JSONArray(ids)).put("new_fingers_use_visible_projection",true).put("held_targets_stable",true).put("last_release_retains_primary",true).put("rule_hash_unchanged",true).put("models",0));
  }
 }

